<?php use App\Support; ?>
<div class="page-head"><div><span class="eyebrow">LỊCH SỬ HOẠT ĐỘNG</span><h1>Nhật ký xử lý</h1><p>Theo dõi các lần nhận đơn, xử lý đơn và gửi kết quả.</p></div></div><section class="panel"><div class="log-list large"><?php foreach ($logs as $log): ?><article><span class="log-dot <?= Support::e($log['level']) ?>"></span><div><b><?= Support::e(Support::friendlyMessage($log['message'])) ?></b><small><?= Support::e(Support::channelLabel($log['channel']).' · '.$log['created_at']) ?><?php if ($log['nas_order_id']): ?> · <a href="/order?id=<?= (int)$log['order_id'] ?>">Đơn #<?= (int)$log['nas_order_id'] ?></a><?php endif; ?></small></div><span class="badge <?= $log['level'] === 'error' ? 'danger' : ($log['level'] === 'warning' ? 'warning' : 'neutral') ?>"><?= $log['level'] === 'error' ? 'Lỗi' : ($log['level'] === 'warning' ? 'Cần chú ý' : 'Thông tin') ?></span></article><?php endforeach; ?><?php if (!$logs): ?><div class="empty">Chưa có hoạt động nào.</div><?php endif; ?></div></section>
